CREATE TABLE users (     id INTEGER PRIMARY KEY,     user_email TEXT UNIQUE NOT NULL,     password TEXT NOT NULL,     user_info TEXT,     created_at DATETIME DEFAULT CURRENT_TIMESTAMP,     updated_at DATETIME DEFAULT CURRENT_TIMESTAMP );
INSERT INTO "users" ("id","user_email","password","user_info","created_at","updated_at") VALUES(1,'nocticur@mourn.top','ebb0087037ffcacf942d096b912c387e85062698c48877aaf3ac5a4adef4c19c','{"source":"admin-bootstrap"}','2026-09-16 04:43:23','2026-09-16 04:43:23');
CREATE TABLE users_address (     id INTEGER PRIMARY KEY,     user_id INTEGER,     address_id INTEGER UNIQUE,     created_at DATETIME DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE user_roles (     id INTEGER PRIMARY KEY,     user_id INTEGER UNIQUE NOT NULL,     role_text TEXT,     created_at DATETIME DEFAULT CURRENT_TIMESTAMP,     updated_at DATETIME DEFAULT CURRENT_TIMESTAMP );
INSERT INTO "user_roles" ("id","user_id","role_text","created_at","updated_at") VALUES(1,1,'master','2026-09-16 04:43:23','2026-09-16 04:43:23');
CREATE TABLE user_passkeys (     id INTEGER PRIMARY KEY,     user_id INTEGER NOT NULL,     passkey_name TEXT NOT NULL,     passkey_id TEXT NOT NULL,     passkey TEXT NOT NULL,     counter INTEGER DEFAULT 0,     created_at DATETIME DEFAULT CURRENT_TIMESTAMP,     updated_at DATETIME DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE redeem_codes (     id INTEGER PRIMARY KEY AUTOINCREMENT,     code TEXT UNIQUE NOT NULL,     redeem_type TEXT NOT NULL,     value TEXT NOT NULL,     result TEXT,     enabled INTEGER NOT NULL DEFAULT 1,     redeemed INTEGER NOT NULL DEFAULT 0 CHECK (redeemed IN (0, 1)),     expires_at DATETIME NOT NULL,     redeemed_at DATETIME,     created_at DATETIME DEFAULT CURRENT_TIMESTAMP,     updated_at DATETIME DEFAULT CURRENT_TIMESTAMP );
DELETE FROM sqlite_sequence;
INSERT INTO "sqlite_sequence" ("name","seq") VALUES('address',5);
CREATE INDEX idx_raw_mails_address ON raw_mails(address);
CREATE INDEX idx_raw_mails_created_at ON raw_mails(created_at);
CREATE INDEX idx_raw_mails_message_id ON raw_mails(message_id);
CREATE INDEX idx_address_name ON address(name);
CREATE INDEX idx_address_created_at ON address(created_at);
CREATE INDEX idx_address_updated_at ON address(updated_at);
CREATE INDEX idx_address_source_meta ON address(source_meta);
CREATE INDEX idx_auto_reply_mails_address ON auto_reply_mails(address);
CREATE INDEX idx_address_sender_address ON address_sender(address);
CREATE INDEX idx_sendbox_address ON sendbox(address);
CREATE INDEX idx_sendbox_created_at ON sendbox(created_at);
CREATE INDEX idx_users_user_email ON users(user_email);
CREATE INDEX idx_users_address_user_id ON users_address(user_id);
CREATE INDEX idx_users_address_address_id ON users_address(address_id);
CREATE INDEX idx_user_roles_user_id ON user_roles(user_id);
CREATE INDEX idx_user_passkeys_user_id ON user_passkeys(user_id);
CREATE UNIQUE INDEX idx_user_passkeys_user_id_passkey_id ON user_passkeys(user_id, passkey_id);
CREATE INDEX idx_redeem_codes_type ON redeem_codes(redeem_type);
